#include <bits/stdc++.h>
using namespace std;const int N=100005;long long a[N],p[N],w[N],b[N];long long e(long long a,long long b,long long&x,long long&y){if(!b)return x=1,y=0,a;long long d=e(b,a%b,y,x);y-=a/b*x;return d;}bool m(long long&r,long long&q,long long x,long long y){long long u,v,g=e(q,y,u,v),d=x-r;if(d%g)return 0;long long z=y/g,t=(__int128)(d/g)*u%z;r=(r+(__int128)q*((t+z)%z))%(q*z);q*=z;return 1;}int main(){ios::sync_with_stdio(0);cin.tie(0);int T;cin>>T;while(T--){int n,k;cin>>n>>k;for(int i=0;i<n;i++)cin>>a[i];for(int i=0;i<n;i++)cin>>p[i];for(int i=0;i<n;i++)cin>>w[i];multiset<long long>s;while(k--){long long x;cin>>x;s.insert(x);}for(int i=0;i<n;i++){auto t=s.upper_bound(a[i]);if(t==s.begin())t=s.begin();else --t;b[i]=*t;s.erase(t);s.insert(w[i]);}long long r=0,q=1,z=0;bool f=1;for(int i=0;i<n;i++){z=max(z,(a[i]+b[i]-1)/b[i]);long long x,y,g=e(b[i],p[i],x,y);if(a[i]%g){f=0;break;}long long v=p[i]/g,u=(__int128)(a[i]/g)*x%v;if(!m(r,q,(u+v)%v,v)){f=0;break;}}if(!f){cout<<-1<<'\n';continue;}if(r<z)r+=(z-r+q-1)/q*q;cout<<r<<'\n';}}
